export interface ConfigurationRevision {
  key: string;
  revision: number;
  payload: string;
}

function validate(record: ConfigurationRevision): void {
  if (
    typeof record !== "object" ||
    record === null ||
    typeof record.key !== "string" ||
    record.key.length === 0 ||
    !Number.isInteger(record.revision) ||
    record.revision < 0 ||
    typeof record.payload !== "string" ||
    record.payload.length === 0
  ) {
    throw new TypeError("Invalid configuration revision");
  }
}

export class RevisionViewer {
  private selected: ConfigurationRevision | undefined;

  initialize(records: readonly ConfigurationRevision[]): void {
    if (!Array.isArray(records)) {
      throw new TypeError("Records must be an array");
    }
    for (const record of records) {
      validate(record);
    }
    if (records.length === 0) {
      this.selected = undefined;
      return;
    }

    let candidate = records[0];
    for (let index = 1; index < records.length; index += 1) {
      if (records[index].revision < candidate.revision) {
        candidate = records[index];
      }
    }
    this.selected = { ...candidate };
  }

  current(): ConfigurationRevision | undefined {
    return this.selected === undefined ? undefined : { ...this.selected };
  }
}
