import { ConfigurationRevision, RevisionViewer } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function expectTypeError(action: () => void, message: string): void {
  let caught: unknown;
  try { action(); } catch (error) { caught = error; }
  assert(caught instanceof TypeError, message);
}

const viewer = new RevisionViewer();
assert(viewer.current() === undefined, "viewer initially has no selection");
const records: ConfigurationRevision[] = [
  { key: "first", revision: 2, payload: "p2-first" },
  { key: "low", revision: 0, payload: "p0" },
  { key: "winner", revision: 7, payload: "p7-first" },
  { key: "tie", revision: 7, payload: "p7-second" },
  { key: "middle", revision: 5, payload: "p5" }
];
const inputSnapshot = records.map((record) => ({ ...record }));
viewer.initialize(records);
const selected1 = viewer.current();
assert(selected1 !== undefined && selected1.key === "winner" && selected1.revision === 7 && selected1.payload === "p7-first", "greatest revision is selected and first tie wins");
assert(records.every((record, index) => record.key === inputSnapshot[index].key && record.revision === inputSnapshot[index].revision && record.payload === inputSnapshot[index].payload), "initialize does not mutate input");
records[2].key = "mutated";
records[2].payload = "mutated";
assert(viewer.current()!.key === "winner" && viewer.current()!.payload === "p7-first", "selected record is copied from input");
selected1!.key = "corrupted";
const selected2 = viewer.current();
assert(selected2 !== selected1 && selected2!.key === "winner", "current returns a fresh copy");

const beforeFailure = viewer.current();
const malformed: unknown[] = [
  null,
  { key: "", revision: 1, payload: "p" },
  { key: 4, revision: 1, payload: "p" },
  { key: "k", revision: -1, payload: "p" },
  { key: "k", revision: 1.5, payload: "p" },
  { key: "k", revision: Number.NaN, payload: "p" },
  { key: "k", revision: 1, payload: "" },
  { key: "k", revision: 1, payload: 5 }
];
for (const bad of malformed) {
  expectTypeError(() => viewer.initialize([bad as ConfigurationRevision]), "malformed records throw TypeError");
  assert(viewer.current()!.key === beforeFailure!.key && viewer.current()!.revision === beforeFailure!.revision, "malformed initialization leaves prior selection unchanged");
}
expectTypeError(() => viewer.initialize([
  { key: "valid", revision: 100, payload: "valid" },
  null as unknown as ConfigurationRevision
]), "all records are validated before selection changes");
assert(viewer.current()!.key === "winner", "late validation failure is atomic");
expectTypeError(() => viewer.initialize(null as unknown as readonly ConfigurationRevision[]), "non-array input throws TypeError");
assert(viewer.current()!.key === "winner", "non-array failure leaves selection unchanged");

viewer.initialize([{ key: " ", revision: 0, payload: " " }]);
assert(viewer.current()!.revision === 0, "zero revision and non-empty string fields are valid boundaries");
viewer.initialize([]);
assert(viewer.current() === undefined, "empty input clears selection");

